import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);  // Inicializando com um array vazio
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Requisição para buscar todos os clientes
    axios.get('http://localhost:8080/clientes')
      .then(response => {
        // Garantir que a resposta seja um array
        if (Array.isArray(response.data)) {
          setClientes(response.data);
        } else {
          setClientes([]);  // Caso a resposta não seja um array
        }
        setLoading(false);
      })
      .catch(err => {
        console.error('Erro ao buscar clientes:', err);
        setError('Erro ao buscar clientes');
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div>Carregando...</div>;
  }

  if (error) {
    return <div>{error}</div>;
  }

  return (
    <div className="cliente-list">
      <h2>Lista de Clientes</h2>
      {/* Verificar se há clientes antes de tentar exibir */}
      {clientes.length > 0 ? (
        <ul>
          {clientes.map(cliente => (
            <li key={cliente.id}>
              {cliente.nome} - {cliente.email} - {cliente.telefone}
            </li>
          ))}
        </ul>
      ) : (
        <p>Não há clientes cadastrados.</p>
      )}
    </div>
  );
};

export default ClienteList;
